            if (sqrtPriceX96 > sqrtLower) {
                uint160 lower = sqrtPriceX96 > sqrtUpper ? sqrtUpper : sqrtPriceX96;
                totalNeed1 += SqrtPriceMath.getAmount1Delta(sqrtLower, lower, liq, true);
